height_min: float = 1
height_max: float = 2


def get_line_from_shape(shape: list[Point2d], index: int) -> tuple[Point2d, Point2d]:
    index_2 = (index + 1) % len(shape)
    return (shape[index], shape[index_2])



def color_rgb(r: float, g: float, b: float) -> int:
    r = int(255*r) % 256
    g = int(255*g) % 256
    b = int(255*b) % 256
    return (r << 16) + (g << 8) + b



def main():
    filename = "./test.m3d"
    filename = os.path.abspath(filename)

    app7 = core.get_KompasAPI7_IApplication()
    app7.Visible = True

    docs = app7.Documents

    for i in range(docs.Count):
        d = docs.Item(i)
        try:
            if os.path.samefile(d.PathName, filename):
                d.Close(constants.DocumentCloseOptions.kdDoNotSaveChanges)
        except:
            pass


    doc = KompasAPI7.IKompasDocument3D(app7.Documents.Add(constants.DocumentTypeEnum.ksDocumentPart, True))
    part: KompasAPI7.IPart7 = doc.TopPart

    doc.HideAllPlanes = True
    doc.HideAllAxis = True

    plane = part.DefaultObject(constants.ksObj3dTypeEnum.o3d_planeXOZ)

    mc = KompasAPI7.IModelContainer(part)
    sketches = mc.Sketchs

    for j, shapes in enumerate(letters_shapes):
        value = j / (len(letters_shapes) - 1)

        sketch = sketches.Add()
        sketch.Plane = plane
        sketch.Update()

        fragm_doc = sketch.BeginEdit()

        vlm = fragm_doc.ViewsAndLayersManager

        view = vlm.Views.View(0)  # системный вид фрагмента (= эскиза) под индексом 0

        dc = KompasAPI7.IDrawingContainer(view)
        # lines = dc.Lines  # это вспомогательные прямые (бесконечной длины)!!!
        line_segments = dc.LineSegments

        for shape in shapes:
            for i in range(len(shape)):
                line_segment = line_segments.Add()
                p1, p2 = get_line_from_shape(shape, i)

                line_segment.X1 = -1 * p1[0]
                line_segment.Y1 = -1 * -p1[1]  # минус, потому что что в svg ось Y сверху вниз, а в Компас наоборот
                line_segment.X2 = -1 * p2[0]
                line_segment.Y2 = -1 * -p2[1]  # минус, потому что что в svg ось Y сверху вниз, а в Компас наоборот

                line_segment.Update()

        # view.Update()

        sketch.EndEdit()

        extrusions = mc.Extrusions
        extrusion = extrusions.Add(constants.ksObj3dTypeEnum.o3d_bossExtrusion)
        extrusion.SetDepth(True, height_min + (height_max - height_min) * value)
        extrusion.Sketch = sketch
        extrusion.Update()

        part_color_param = KompasAPI7.IColorParam7(extrusion)
        r = 1
        g = 1 - value if value <= 0.5 else (1 - 2 * (value - 0.5)) * 0.5
        b = 1 - 2 * value if value <= 0.5 else (value - 0.5) * 0.5
        part_color_param.Color = core.color_traditional_to_kompas(color_rgb(r, g, b))

        extrusion.Update()

        part.Update()

        app7.ExecuteKompasCommand(constants.ksCMZoomEntireDocument, True)

    doc.SaveAs(filename)




if __name__ == "__main__":
    main()
